# ! [doc = " Type metadata identifiers for LLVM Control Flow Integrity (CFI) and cross-language LLVM CFI"] # ! [doc = " support for the Rust compiler."] # ! [doc = ""] # ! [doc = " For more information about LLVM CFI and cross-language LLVM CFI support for the Rust compiler,"] # ! [doc = " see design document in the tracking issue #89653."] use split_decls_genesis :: ourprelude :: * ; use bitflags :: bitflags ; use rustc_middle :: ty :: { Instance , Ty , TyCtxt } ; use rustc_target :: callconv :: FnAbi ; bitflags ! { #[doc = " Options for typeid_for_fnabi."] #[derive (Clone , Copy , Debug)] pub struct TypeIdOptions : u32 { #[doc = " Generalizes pointers for compatibility with Clang"] #[doc = " `-fsanitize-cfi-icall-generalize-pointers` option for cross-language LLVM CFI and KCFI"] #[doc = " support."] const GENERALIZE_POINTERS = 1 ; #[doc = " Generalizes repr(C) user-defined type for extern function types with the \"C\" calling"] #[doc = " convention (or extern types) for cross-language LLVM CFI and  KCFI support."] const GENERALIZE_REPR_C = 2 ; #[doc = " Normalizes integers for compatibility with Clang"] #[doc = " `-fsanitize-cfi-icall-experimental-normalize-integers` option for cross-language LLVM"] #[doc = " CFI and  KCFI support."] const NORMALIZE_INTEGERS = 4 ; #[doc = " Do not perform self type erasure for attaching a secondary type id to methods with their"] #[doc = " concrete self so they can be used as function pointers."] #[doc = ""] #[doc = " (This applies to typeid_for_instance only and should be used to attach a secondary type"] #[doc = " id to methods during their declaration/definition so they match the type ids returned by"] #[doc = " either typeid_for_instance or typeid_for_fnabi at call sites during code generation for"] #[doc = " type membership tests when methods are used as function pointers.)"] const USE_CONCRETE_SELF = 8 ; } } pub mod itanium_cxx_abi ; #[doc = " Returns a type metadata identifier for the specified FnAbi."] pub fn typeid_for_fnabi < 'tcx > (tcx : TyCtxt < 'tcx > , fn_abi : & FnAbi < 'tcx , Ty < 'tcx > > , options : TypeIdOptions ,) -> String { itanium_cxx_abi :: typeid_for_fnabi (tcx , fn_abi , options) } #[doc = " Returns a type metadata identifier for the specified Instance."] pub fn typeid_for_instance < 'tcx > (tcx : TyCtxt < 'tcx > , instance : Instance < 'tcx > , options : TypeIdOptions ,) -> String { itanium_cxx_abi :: typeid_for_instance (tcx , instance , options) }